from ode import *
coeff={1:(1,-1,-6),2:(1,-6,9),3:(1,0,2),4:(1,1,-12),5:(4,4,1),6:(9,0,4),7:(3,-4,0),8:(1,0,-1),9:(1,-4,13),10:(3,4,-3),11:(2,2,-1),12:(1,6,34),13:(3,4,3),14:(4,-4,1),15:(1,2,2),16:(2,1,-1)}
features={14:('Every solution tends to 0 as x→−∞; nonzero solutions grow without bound in magnitude as x→∞','All solutions tend to 0 as x→∞'),15:('All solutions tend to 0 as x→∞; nonzero solutions oscillate with decaying envelope','All nonzero solutions increase monotonically'),16:('No oscillations; at most one zero for a nonzero solution; e^(x/2) grows and e^(−x) decays as x→∞','Every solution tends to 0 as x→∞')}
for k,abc in coeff.items():
 sol=solve(abc); fs=[answer(sol,abc,var=t if 11<=k<=13 else x,label=('R(t)' if k==12 else 'V(t)' if k==13 else 'y(t)' if k==11 else 'y(x)'))]
 if k in features:fs+=[c('Common graph features',*features[k],'All nonzero solutions are periodic')]
 A.row(1,k,*fs,limited=k in features,why='Substitute e^(rx); solve ar²+br+c=0. Distinct real roots give two exponentials; a repeated root requires x e^(rx); complex roots give a sine/cosine pair. Direct substitution verifies the solution.')
for k,abc,data in [(17,(1,0,3),iv(1,3)),(18,(1,-2,-3),iv(2,2)),(19,(9,12,4),iv(1,0)),(20,(3,-2,-1),iv(0,-4)),(21,(1,-6,10),iv(2,3)),(22,(4,-20,25),iv(2,-3)),(23,(1,-1,-12),iv(0,1,1)),(24,(4,4,3),iv(0,1))]:
 A.row(1,k,answer(solve(abc,ics=data),abc),why='Use both initial conditions to determine the two constants; the equation and both initial values are independently substituted back.')
for k,abc,data in [(25,(1,0,16),{'y':[(0,-3),(pi/8,2)]}),(26,(1,6,0),{'y':[(0,1),(1,0)]}),(27,(1,4,4),{'y':[(0,2),(1,0)]}),(29,(1,-1,0),{'y':[(0,1),(1,2)]}),(30,(4,-4,1),{'y':[(0,4),(2,0)]})]:
 A.row(1,k,answer(solve(abc,ics=data),abc),why='Apply the two endpoint conditions to the general solution and solve the two linear equations.')
for k,why in [(28,'y(0)=3 forces y(π)=−3e^(4π), so it cannot equal 2.'),(31,'y(0)=1 forces y(π)=e^(−2π), which is not 2.')]:A.row(1,k,c('Boundary-value result','No solution','Exactly one solution','Infinitely many solutions'),why=why)
A.row(1,32,c('All solutions','y=e^(−2x)[cos(4x)+C sin(4x)], C arbitrary','y=e^(−2x)[2cos(4x)+C sin(4x)]','No solution'),why='The sine term is zero at both endpoints; either boundary fixes the cosine coefficient at 1, leaving the sine coefficient free.')
A.row(1,33,c('a · λ≤0','Only y=0','y=Cx with arbitrary C','Every exponential solves both endpoints'),c('b · Eigenvalues','λ=(nπ/L)², n=1,2,…','λ=nπ/L','Every positive λ'),c('b · Corresponding nonzero solutions','y=C sin(nπx/L), C≠0','y=C cos(nπx/L), C≠0','y=C exp(nπx/L), C≠0'),limited=True,why='For λ<0 use real exponentials, and for λ=0 use a line; two zero endpoints force both coefficients to vanish. For λ>0, sin(√λ L)=0 supplies the discrete eigenvalues.')
A.row(1,34,n('Limit as x→∞',0),c('Reason','Both real roots are negative, or the complex roots have negative real part −b/(2a)','Both characteristic roots must be positive','A positive constant solution always exists'),limited=True,why='For real roots their product c/a is positive and sum −b/a negative; for complex roots the common real part is negative. Even x e^(rx) decays when r<0.')
A.row(1,35,c('a · Unique solution','b−a is not an integer multiple of π','b−a is an integer multiple of π','a+b=0'),c('b · No solution','b−a=nπ and d≠(−1)^n exp(b−a)c','b−a=nπ and d=(−1)^n exp(b−a)c','sin(b−a)≠0'),c('c · Infinitely many','b−a=nπ and d=(−1)^n exp(b−a)c','sin(b−a)≠0','b−a=nπ and d≠(−1)^n exp(b−a)c'),why='Write y=e^x(A cos x+B sin x). The endpoint matrix determinant is proportional to sin(b−a); when it vanishes the second row is a signed exponential multiple of the first.')
save('section01')
